        "code": "EXPOSURE_SPARSITY",
        "text": "Many play types, especially when further conditioned on own-sequence lags, will have too few occurrences to estimate opponent PPP with adequate precision."
      },
      {
        "code": "CONFOUNDING",
        "text": "Opponent next-possession PPP is strongly confounded by overall opponent offensive quality, game score differential, and period, mimicking the team-quality confound that limited FAM:SF-CHT-039."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF-APPA-005",
      "FAM:SF-APPA-050",
      "FAM:SF-CHT-039",
      "FAM:SF-CHT-086"
    ],
    "summary": "No prior study directly tested whether opponent next-possession PPP after specific play types is sufficiently large and robust to drive AVOID labels. However, closely related work on suppression labels and AVOID share found that outcome-derived labels are susceptible to RTM artifacts, label noise, and confounding, and that observed effects often shrink or disappear under proper validation."
  },
  "risks": [
    {
      "code": "RTM_SELECTION",
      "text": "Selecting play types for AVOID labeling based on high observed opponent next-possession PPP is selecting on the outcome, which inflates apparent effects and creates RTM artifacts."
    },
    {
      "code": "LABEL_ERROR",
      "text": "Play-type labels from the graph database, possession boundaries, and opponent PPP computations contain noise that can mask or mimic true signal, as documented in FAM:SF-APPA-005."
    },
    {
      "code": "CONFOUNDING",
      "text": "Opponent next-possession outcomes are confounded by opponent offensive ability, game state (score margin, period), and team defensive quality; failing to fully adjust for these will bias effect estimates."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "Many play types occur infrequently, making per-type opponent PPP estimates noisy and underpowered, especially when split by own-sequence lag."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Testing many play types and lags without multiplicity correction risks false positives, as was the case in FAM:SF-APPA-050."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "If AVOID labels are defined using full-season or future data and then applied to past decisions, look-ahead bias can overstate predictability, analogous to the leakage in FAM:SF-CHT-086."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.05,
    "untestable": 0.25,
    "artifact": 0.45,
    "uncertain": 0.20
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Average opponent points per possession on the first possession following each play type, adjusted for score differential, period, opponent offensive rating, and home/away, using only out-of-sample data for labeling thresholds.",
    "unit": "Possession immediately following a labeled play-type possession.",
    "sample": "All regular-season and playoff possessions from 2022-23 through 2025-26 where a play-type label is assigned and a valid next possession by the opponent exists, excluding end-of-quarter and end-of-game possessions without a subsequent possession.",
    "power": "Require at least 200 occurrences per play-type for inclusion; at that sample, a 0.05 PPP shift can be detected with 80% power at α=0.05 under typical variance. Play types with fewer occurrences are grouped into a broader category.",
    "controls": "Score differential (categorical: trailing, tie, leading), game period, opponent defensive rating (season-level, lagged), home/away indicator, starter/bench status of the offensive lineup, and rest days.",
    "falsification": "Split the data temporally: train on 2022-23 to 2024-25, test whether play types identified as having high opponent PPP in the training set replicate in 2025-26. Use placebo lags (e.g., two possessions later) to check specificity.",
    "multiplicity": "Benjamini-Hochberg FDR correction at 0.05 across all play types tested for both opponent next-possession PPP and own-sequence lags.",
    "decision_rule": "A play type is flagged as potentially AVOID-worthy only if, after FDR correction, its opponent next-possession PPP is significantly above the league-average opponent PPP in the out-of-sample test, and the effect size exceeds 0.04 PPP (about 0.5 points per 100 possessions).",
    "data_version": "NBA per-game files 2022-23 through 2025-26 as of 2026-06-19."
  }
}

